function missions(){open(tr('<h2>ฐานจำลอง 100 ด่าน</h2><p>ทำลายฐานแม่เพื่อชนะและปลดล็อกด่านถัดไป • ฐานแม่แตกได้ 70% ทำลายครบได้ 100%<br>เลือกจุดปล่อยทหารที่ขอบสนาม แล้วกองทัพจะโจมตีอัตโนมัติ</p><div class="missions">')+Array.from({length:100},function(_,i){var n=i+1;return'<button '+(n>E.d.stage?'disabled':'')+' onclick="Game.scout('+n+')">'+n+(n%10===0?' ★':'')+'<small>'+(E.d.stars[n]?'★'.repeat(E.d.stars[n]):n>E.d.stage?tr('ล็อก'):tr('สำรวจ'))+'</small></button>';}).join('')+tr('</div><button class="wide" onclick="Game.close()">กลับฐาน</button>'));}
function result(){var r=E.raid.result;if(E.raid.practice){open(tr('<h2>ผลการบุกทดสอบ</h2><p>ทำลาย ')+r.percent+'% • '+r.stars+tr(' ดาว<br>คุณวางกำลังเองและดูการต่อสู้ในสนาม<br>สนามซ้อมไม่หักทหารหรือทรัพยากรเจ้าของฐาน</p><button class="wide green" onclick="Game.practiceAgain()">สุ่มฐานถัดไป</button><button class="wide" onclick="Game.home()">กลับฐาน</button>'));hud();return;}open('<h2>'+(r.stars?tr('ภารกิจสำเร็จ'):tr('ถอนกำลัง'))+'</h2><div class="stars">'+'★'.repeat(r.stars)+'☆'.repeat(3-r.stars)+tr('</div><p>ทำลาย ')+r.percent+tr('%<br>ได้ ')+r.gold+tr(' ทอง และ ')+r.power+tr(' พลังงาน</p><p>กำลังพลที่รอดชีวิตกลับฐานแล้ว<br>ทหารที่ยังไม่ปล่อยยังอยู่ในค่าย</p><button class="wide green" onclick="Game.home()">กลับฐาน</button>'));hud();}
function pause(){if(screen==='defense'){if(E.defense.result)return;paused=true;open(tr('<h2>พักป้องกันฐาน</h2><button class="wide green" onclick="Game.resume()">เล่นต่อ</button><button class="wide" onclick="Game.endDefense()">จบการป้องกัน (ไม่ได้รางวัล)</button>'));return;}if(screen!=='raid'||!E.raid||E.raid.result)return;paused=true;open(tr('<h2>พักการรบ</h2><button class="wide green" onclick="Game.resume()">เล่นต่อ</button><button class="wide" onclick="Game.retreat()">ถอนกำลังและรับทรัพยากรที่ได้</button>'));}
